// Best-effort extraction. n8n's Error Trigger payload shape/depth varies
// by version and by what kind of failure occurred (node failure vs
// trigger failure), so treat everything here as best-effort — if
// actionId can't be recovered, that's a normal, expected outcome (see
// the IF node right after this one), not a bug.
const evt = $input.first().json;
const execution = evt.execution || {};
const workflow = evt.workflow || {};
const errorMessage = execution.error?.message || evt.trigger?.error?.message || 'Unknown n8n execution error.';

let actionId;
try {
  const runData = execution.data?.resultData?.runData || {};
  for (const nodeName of Object.keys(runData)) {
    for (const run of runData[nodeName]) {
      const items = run?.data?.main?.[0] || [];
      for (const item of items) {
        const candidate = item?.json?.actionId || item?.json?.action?.id;
        if (candidate) { actionId = candidate; break; }
      }
      if (actionId) break;
    }
    if (actionId) break;
  }
} catch (e) {
  // Swallow — this is genuinely best-effort, see note above.
}

return [{
  json: {
    actionId: actionId || null,
    errorMessage,
    workflowName: workflow.name,
    executionId: execution.id,
  },
}];
